CREATE TABLE a (id INT PRIMARY KEY, nombre VARCHAR(10), valor FLOAT, creado DATE);
CREATE TABLE b (id INT PRIMARY KEY, a_id INT, activo BOOLEAN);
SELECT zz FROM a;
SELECT id FROM a INNER JOIN b ON a.id = b.a_id;
SELECT q.id FROM a;
SELECT nombre FROM a WHERE valor = 'caro';
SELECT nombre FROM a WHERE creado > 'ayer';
SELECT nombre FROM a WHERE valor;
SELECT nombre FROM a WHERE COUNT(*) > 1;
SELECT nombre, COUNT(*) FROM a;
SELECT SUM(nombre) FROM a;
SELECT nombre FROM a WHERE id IN (SELECT id, a_id FROM b);
SELECT nombre FROM a WHERE valor = (SELECT id, a_id FROM b);
SELECT nombre FROM a WHERE id IN (SELECT activo FROM b);
SELECT nombre FROM fantasma;
SELECT a.nombre FROM a INNER JOIN a ON a.id = a.id;
UPDATE a SET zz = 1;
UPDATE a SET nombre = 5, nombre = 'x';
DELETE FROM a WHERE zz = 1;
SELECT activo > TRUE FROM b;
